-- ==========================================================
-- Schema & Seed Data for table `site_blogs`
-- ==========================================================

CREATE TABLE IF NOT EXISTS `site_blogs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `meta_keywords` varchar(500) DEFAULT NULL,
  `category` varchar(100) NOT NULL DEFAULT 'tech',
  `category_name` varchar(150) DEFAULT 'AI & Tech',
  `author_name` varchar(150) NOT NULL DEFAULT 'Faculty Contributor',
  `author_role` varchar(255) DEFAULT NULL,
  `publish_date` date NOT NULL,
  `read_time` varchar(50) DEFAULT '5 min read',
  `tags` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_cat` (`category`),
  KEY `idx_status` (`status`),
  KEY `idx_featured` (`is_featured`),
  KEY `idx_pdate` (`publish_date`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Default seed data (Total: 8 rows)
INSERT IGNORE INTO `site_blogs` (`id`, `title`, `slug`, `meta_title`, `meta_description`, `meta_keywords`, `category`, `category_name`, `author_name`, `author_role`, `publish_date`, `read_time`, `tags`, `summary`, `content`, `image`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES
('1', 'Commercializing Academic Research: How Bhabha University Developed 14 Proprietary Herbal & Pharmacy Formulations', 'commercializing-academic-research-14-formulations', 'Commercializing Academic Research: 14 Herbal Formulations | Bhabha University', 'Learn how Bhabha University faculty and scholars developed and commercialized 14 proprietary herbal and pharmacy formulations through dedicated clinical trials.', 'Herbal Research, Pharmacy Formulations, Bhabha University Bhopal, Academic Research Commercialization, Drug Development', 'pharmacy', 'Pharmacy & Innovation', 'Dr. S. K. Verma', 'Dean, Research & Pharmaceutical Sciences • Bhabha University', '2026-08-15', '5 min read', 'PharmaResearch, Patents, HerbalFormulations, Innovation', 'Translating laboratory discoveries into commercially viable healthcare products is the hallmark of modern university research. At Bhabha University, our dedicated team of pharmaceutical researchers, faculty innovators, and student scholars engineered 14 breakthrough formulations—from advanced antimicrobial ointments to herbal immunomodulators. Here is a look at the methodology, regulatory clearances, and the patent roadmap that made it possible.', '<p>Translating laboratory discoveries into commercially viable healthcare products is the hallmark of modern university research. At Bhabha University, our dedicated team of pharmaceutical researchers, faculty innovators, and student scholars engineered 14 breakthrough formulations—from advanced antimicrobial ointments to herbal immunomodulators. Here is a look at the methodology, regulatory clearances, and the patent roadmap that made it possible.</p><p>Our state-of-the-art pharmaceutics and pharmacognosy laboratories operate under rigorous cGMP and GLP compliance protocols. The development pipeline engaged multi-disciplinary teams across chemical analysis, stability testing, microbial screening, and clinical safety validations.</p><p>Key commercial approvals achieved include FSSAI, MSME, and MP State Drug Licensing. For further licensing inquiries or collaborative R&D programs, please contact our Directorate of Research.</p>', 'upload/media/blog_herbal_pharmacy_research.jpg', '1', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('2', 'Architecting Resilient Cloud Infrastructure with Edge AI', 'architecting-resilient-cloud-edge-ai', 'Architecting Resilient Cloud Infrastructure with Edge AI | Bhabha University', 'How distributed edge computing and lightweight machine learning models are transforming real-time data processing in enterprise environments.', 'Edge AI, Cloud Infrastructure, Distributed Machine Learning, Computer Science, Bhabha University', 'tech', 'AI & Tech', 'Prof. Amit Sen', 'Dept. of Computer Science & Engineering', '2026-07-20', '4 min read', 'CloudComputing, EdgeAI, IoT', 'How distributed edge computing and lightweight machine learning models are transforming real-time data processing in IoT sensors and smart manufacturing.', '<p>Edge computing brings computation and data storage closer to the sources of data. This improves response times and saves bandwidth. When integrated with lightweight Edge AI models, devices can perform real-time inferences without continuous cloud connectivity, critical in autonomous vehicles, smart farming, and hospital telemedicine equipment.</p><p>In this article, we evaluate tensor quantization methods and resource-constrained inference engines suited for industrial microcontroller platforms tested within our campus robotics and automation lab.</p>', 'upload/media/blog_cloud_edge_ai.jpg', '0', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('3', 'Next-Generation Targeted Drug Delivery via Lipid Nanoparticles', 'targeted-drug-delivery-lipid-nanoparticles', 'Next-Generation Targeted Drug Delivery via Lipid Nanoparticles | Bhabha University', 'A comprehensive exploration of lipid nanoparticle systems in oncology and mRNA therapeutics, minimizing systemic cytotoxicity.', 'Targeted Drug Delivery, Lipid Nanoparticles, Oncology, Pharmacy Research, Bhabha University Bhopal', 'pharmacy', 'Pharmacy & Health', 'Dr. Manisha Joshi', 'Faculty of Pharmacy', '2026-06-12', '6 min read', 'Nanomedicine, DrugDelivery, PharmaResearch', 'A comprehensive exploration of lipid nanoparticle systems in oncology and mRNA therapeutics, minimizing systemic side effects and improving bioavailability.', '<p>Targeted drug delivery represents one of the most promising frontiers in modern pharmacotherapy. By encapsulating therapeutic agents in engineered lipid nanoparticles (LNPs), drugs can bypass biological barriers and release active ingredients specifically at diseased tissue sites.</p><p>Our research team has synthesized novel ionizable lipids that demonstrate heightened cell transfection rates while reducing non-target organ accumulation in preclinical models.</p>', 'upload/media/blog_nanoparticle_delivery.jpg', '0', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('4', 'Mastering Technical & HR Interviews in Top Tier Companies', 'mastering-technical-and-hr-interviews', 'Mastering Technical & HR Interviews in Top Tier Companies | Bhabha University', 'Essential strategies for engineering and management students preparing for campus placement rounds with multinational recruiters.', 'Campus Placements, Technical Interviews, HR Interview Preparation, Career Guidance, Bhabha University', 'career', 'Career & Placements', 'T&P Cell Advisory', 'Training & Placement Directorate', '2026-05-18', '5 min read', 'PlacementTips, CareerGrowth, InterviewSkills', 'Essential strategies for engineering and management students preparing for campus placement rounds with IT majors, banking giants, and MNCs.', '<p>Cracking campus placements requires a balance of core domain competence, problem-solving dexterity, and soft skills communication. Focus on Data Structures, fundamental business case studies, active listening, and showcasing live project contributions during technical rounds.</p><p>Mock behavioral interviews and peer problem-solving groups conducted each semester provide students with hands-on exposure to high-pressure screening stages.</p>', 'upload/media/blog_interview_mastery.jpg', '0', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('5', 'Navigating the Patent Filing Process for Student Innovators', 'patent-filing-process-student-innovators', 'Navigating the Patent Filing Process for Student Innovators | Bhabha University', 'Step-by-step guidance on prior-art search, patent drafting, provisional applications, and institutional IP facilitation at Bhabha University.', 'Patent Filing, Student Innovators, Intellectual Property Rights, IPR Cell, Bhabha University Bhopal', 'research', 'Patents & Research', 'IPR Cell Coordinator', 'IPR & Incubation Cell', '2026-04-10', '7 min read', 'Patents, IPR, Innovation', 'Step-by-step guidance on prior-art search, patent drafting, provisional applications, and institutional support provided by Bhabha University IPR Cell.', '<p>Protecting intellectual property early in the development lifecycle gives inventors a significant competitive edge. Bhabha University provides comprehensive legal and financial assistance for eligible student and faculty inventions via our IPR Facilitation Cell.</p><p>We walk aspiring inventors through Indian Patent Office classification schemas, novelty requirements, and drafting claims that withstand scrutiny during examination phases.</p>', 'upload/media/blog_patent_process.jpg', '0', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('6', 'Sustainable Energy Harvesting for Smart Cities & Campus IoT', 'sustainable-energy-harvesting-campus-iot', 'Sustainable Energy Harvesting for Smart Cities & Campus IoT | Bhabha University', 'Examining low-power micro-generators, piezoelectric pavements, and solar rooftop integration tested on our campus microgrid.', 'Sustainable Energy, Smart Cities, Campus IoT, Clean Energy Harvesting, Bhabha University', 'tech', 'AI & Tech', 'Dept. of Electrical Engg', 'Faculty of Engineering & Technology', '2026-03-25', '4 min read', 'CleanTech, GreenEnergy, SmartCampus', 'Examining low-power micro-generators, piezoelectric pavements, and solar rooftop integration tested on the Bhabha University green campus.', '<p>Transitioning towards carbon-neutral smart campuses requires innovative energy harvesting techniques. By deploying localized solar trackers and micro-wind installations, institutions can sustainably power smart streetlights and sensor networks.</p><p>Field measurements collected across 5 campus demonstration sites indicate an average 18% energy self-sufficiency during peak daytime operational loads.</p>', 'upload/media/blog_smart_energy_iot.jpg', '0', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('7', 'Effective Habits for Academic Excellence & Mental Well-being', 'habits-academic-excellence-mental-wellbeing', 'Effective Habits for Academic Excellence & Mental Well-being | Bhabha University', 'Practical psychological tools, active recall learning methods, and stress resilience practices for university undergraduates.', 'Academic Excellence, Mental Well-being, Study Habits, Student Wellness, Bhabha University Bhopal', 'career', 'Career & Placements', 'Student Counseling Cell', 'Student Welfare & Counseling Cell', '2026-02-14', '3 min read', 'StudentLife, StudyTips, MentalHealth', 'Practical psychological tools, active recall learning methods, and stress resilience practices for university scholars during exam seasons.', '<p>Academic success is directly linked with cognitive balance and physical health. Implementing spaced repetition, scheduled digital detox intervals, and participating in extracurricular sports significantly enhances memory retention and reduces anxiety.</p><p>The Student Welfare cell hosts regular mindfulness circles, peer counseling seminars, and physical fitness workshops open to all undergraduate and postgraduate cohorts.</p>', 'upload/media/blog_academic_wellness.jpg', '0', '1', '2026-09-09 13:07:30', '2026-09-09 17:14:35'),
('9', 'Digital Marketing Careers in 2026–27: The Skills Agencies Actually Hire For', 'digital-marketing-careers-2026-27', 'Digital Marketing Careers 2026–27: Skills, Roles & AI Search', 'Planning a digital marketing career in 2026–27? Learn the skills agencies hire for, from SEO and AEO to GEO and AI search, plus a 90-day starter plan.', 'digital marketing careers 2026–27, digital marketing skills, SEO career, AI search, AEO and GEO, digital marketing jobs for freshers', 'career', 'Career & Placements', 'Abhishek Raikwar', 'Founder, Digital4Local', '2026-10-03', '8 min read', 'DigitalMarketing, SEO, AEO, GEO, AISearch, CareerGuide', 'A digital marketing career in 2026–27 needs more than social media and ads. Agencies now hire freshers who understand search in all its forms: Google rankings (SEO), direct answers (AEO) and AI tools like ChatGPT and Google AI Overviews (GEO). This guide covers the roles open to students, the skills that matter, and a 90-day plan to get job-ready.', '<p>A digital marketing career in 2026–27 needs more than social media and ads. Agencies now hire freshers who understand search in all its forms: Google rankings (SEO), direct answers (AEO) and AI tools like ChatGPT and Google AI Overviews (GEO). This guide covers the roles open to students, the skills that matter, and a 90-day plan to get job-ready.</p>\n<h2>Why is digital marketing changing in 2026–27?</h2>\n<p>People no longer find businesses only by clicking blue links. They ask ChatGPT, Perplexity or Gemini, and they read Google&#039;s AI Overviews at the top of the results page. Google says AI Overviews now appear in more than 200 countries and territories and in over 40 languages, and that in India and the US they have increased Search use for the questions where they appear (<a href=\"https://blog.google/products/search/ai-overview-expansion-may-2025-update/\" target=\"_blank\" rel=\"noopener\">Google, May 2025</a>).</p>\n<p>That changes what marketers do. Ranking on Google still matters. But a business also needs to be the source an AI tool quotes when it writes its answer.</p>\n<p>For students, this is good news. These skills are new, so the gap between a fresher and an experienced marketer is smaller here than in almost any other area of marketing.</p>\n<h2>What are SEO, AEO and GEO?</h2>\n<p>These three terms appear in almost every 2026 job description for search roles. Here is the plain-language version.</p>\n<table class=\"table table-bordered\">\n  <tr>\n    <th>Term</th>\n    <th>Full form</th>\n    <th>What it means</th>\n    <th>Where you see it</th>\n  </tr>\n  <tr>\n    <td>SEO</td>\n    <td>Search Engine Optimization</td>\n    <td>Helping a website rank in Google&#039;s regular results</td>\n    <td>The ten blue links</td>\n  </tr>\n  <tr>\n    <td>AEO</td>\n    <td>Answer Engine Optimization</td>\n    <td>Structuring content so search engines lift it as a direct answer</td>\n    <td>Featured snippets, &quot;People also ask&quot;, voice assistants</td>\n  </tr>\n  <tr>\n    <td>GEO</td>\n    <td>Generative Engine Optimization</td>\n    <td>Making a brand the source AI tools trust and cite</td>\n    <td>ChatGPT, Perplexity, Gemini, Google AI Overviews</td>\n  </tr>\n</table>\n<p>They are not three separate careers. They are three layers of the same job: getting found when someone has a question. GEO is the newest of the three, so it is worth reading <a href=\"https://digital4local.com/blog/what-is-geo-generative-engine-optimisation\" target=\"_blank\" rel=\"noopener\">a plain-English guide to what generative engine optimisation is</a> before your first interview.</p>\n<h2>Which digital marketing roles are open to freshers?</h2>\n<p>Most entry-level roles fall into five groups. Your degree matters less than your portfolio, but some backgrounds give you a head start.</p>\n<table class=\"table table-bordered\">\n  <tr>\n    <th>Role</th>\n    <th>What you do day to day</th>\n    <th>Core skills</th>\n    <th>Natural fit for</th>\n  </tr>\n  <tr>\n    <td>SEO / AI search executive</td>\n    <td>Keyword research, content briefs, fixing site issues, tracking AI citations</td>\n    <td>Search tools, writing, basic HTML</td>\n    <td>BBA, MBA, BCA, B.Tech</td>\n  </tr>\n  <tr>\n    <td>Content writer / strategist</td>\n    <td>Writing blogs, guides and pages that rank and get cited</td>\n    <td>Clear writing, research, structure</td>\n    <td>BA, Mass Comm, English, MBA</td>\n  </tr>\n  <tr>\n    <td>Performance marketing executive</td>\n    <td>Running Google and Meta ad campaigns, managing budgets</td>\n    <td>Analytics, testing, numbers</td>\n    <td>BBA, B.Com, MBA</td>\n  </tr>\n  <tr>\n    <td>Social media executive</td>\n    <td>Planning content, community management, short video</td>\n    <td>Platform trends, editing, copy</td>\n    <td>BA, Mass Comm, BBA</td>\n  </tr>\n  <tr>\n    <td>Marketing analyst</td>\n    <td>Reporting, dashboards, finding what is working</td>\n    <td>Excel, Google Analytics, Looker Studio</td>\n    <td>B.Com, BCA, MBA (Analytics)</td>\n  </tr>\n</table>\n<h2>What skills do agencies look for in 2026–27?</h2>\n<p>Tools change every year. These seven skills do not.</p>\n<ul>\n  <li><strong>Search fundamentals.</strong> Know how Google crawls, indexes and ranks a page.</li>\n  <li><strong>AI search literacy.</strong> Understand how AI tools choose which sources to quote, and test it yourself.</li>\n  <li><strong>Clear writing.</strong> Write short sentences that answer a question in the first two lines.</li>\n  <li><strong>Structured content.</strong> Use headings, lists, tables and FAQs that both people and machines can read.</li>\n  <li><strong>Data reading.</strong> Open Google Analytics or Search Console and explain one chart in plain words.</li>\n  <li><strong>Local search basics.</strong> Know how a <a href=\"https://support.google.com/business/answer/3038063\" target=\"_blank\" rel=\"noopener\">Google Business Profile</a> controls the way a business appears on Maps and Search, and why reviews matter.</li>\n  <li><strong>Client communication.</strong> Report progress without jargon.</li>\n</ul>\n<h2>How do agencies evaluate freshers?</h2>\n<p>Agencies rarely shortlist on marks. They look for proof that you can think about search the way a client&#039;s customer does.</p>\n<p>At <a href=\"https://digital4local.com/\" target=\"_blank\" rel=\"noopener\">Digital4Local</a>, a local SEO and AI search agency based in Bhopal that works with businesses in the UK and India, one of the first questions we ask a fresher is simple: ask ChatGPT for the best service provider in your area, then explain why it named those businesses.</p>\n<p>A good answer mentions reviews, consistent business details across the web, and clear content that answers real questions. A great answer comes with screenshots and a one-page note on what the missing businesses should fix. That single exercise tells us more than a certificate.</p>\n<h2>How can you build experience while still in college?</h2>\n<p>You do not need a job to build a portfolio. Pick two or three of these projects and document each one.</p>\n<ul>\n  <li><strong>Audit a local business.</strong> Choose a shop or clinic near campus. Check its Google Business Profile, reviews and website, and write five fixes.</li>\n  <li><strong>Run an AI visibility test.</strong> Ask ChatGPT, Gemini and Perplexity the same 10 questions about a local service. Record who gets mentioned and why.</li>\n  <li><strong>Start a niche blog.</strong> Write ten useful posts on a topic you know. Track which ones get impressions in Google Search Console.</li>\n  <li><strong>Grow a LinkedIn profile.</strong> Post weekly about what you are learning. Recruiters read these.</li>\n  <li><strong>Help a campus club or event.</strong> Handle its social media or registrations page, and report the results with numbers.</li>\n</ul>\n<p>Keep every project to one page: the problem, what you did, and what changed.</p>\n<h2>What does a 90-day plan look like?</h2>\n<p>This plan fits alongside regular classes at roughly one hour a day.</p>\n<ul>\n  <li><strong>Days 1–30: Learn the foundations.</strong> Complete one free course from the list below, read Google&#039;s own <a href=\"https://developers.google.com/search/docs/fundamentals/seo-starter-guide\" target=\"_blank\" rel=\"noopener\">SEO Starter Guide</a>, and set up a practice blog connected to <a href=\"https://search.google.com/search-console/about\" target=\"_blank\" rel=\"noopener\">Google Search Console</a>.</li>\n  <li><strong>Days 31–60: Build two portfolio projects.</strong> Do one local business audit and one AI visibility test. Write each up as a one-page case.</li>\n  <li><strong>Days 61–90: Get visible.</strong> Publish your projects on LinkedIn, apply for internships, and ask for feedback from people already working in agencies.</li>\n</ul>\n<h2>Which free certifications are worth doing?</h2>\n<p>Certificates do not get you hired on their own, but they show you finished something. These are free and widely recognised.</p>\n<ul>\n  <li><a href=\"https://skillshop.withgoogle.com/\" target=\"_blank\" rel=\"noopener\"><strong>Google Skillshop</strong></a><strong>:</strong> Free training and certifications for Google Ads and Google Analytics</li>\n  <li><a href=\"https://academy.hubspot.com/courses/seo-training\" target=\"_blank\" rel=\"noopener\"><strong>HubSpot Academy</strong></a><strong>:</strong> Free certification courses, including one on answer engine optimisation (AEO)</li>\n  <li><a href=\"https://www.semrush.com/academy/certification/\" target=\"_blank\" rel=\"noopener\"><strong>Semrush Academy</strong></a><strong>:</strong> Free SEO, content and social media courses with certificates</li>\n  <li><a href=\"https://developers.google.com/search/docs\" target=\"_blank\" rel=\"noopener\"><strong>Google Search Central</strong></a><strong>:</strong> Not a certificate, but the official documentation on how Google Search works</li>\n</ul>\n<h2>Can you work with international clients from India?</h2>\n<p>Yes. Search skills are location-independent. Many Indian agencies and freelancers already serve clients in the UK, US and Australia.</p>\n<p>Working across borders teaches you different markets, time-zone discipline and written client communication. Start with English writing practice and one portfolio project aimed at an overseas business.</p>\n<h2>Your next step</h2>\n<p>Digital marketing in 2026–27 rewards people who understand how answers are found, by Google and by AI. Pick one project from this guide and finish it this month. A finished project beats a long list of plans.</p>\n<h2>Frequently Asked Questions</h2>\n<p><strong>Is digital marketing a good career in 2026–27?</strong> Yes, for students who build practical skills. AI search has changed how businesses get found, and agencies need people who understand Google rankings, direct answers and AI citations together. Because these skills are new, freshers with a strong portfolio can compete with more experienced candidates.</p>\n<p><strong>What is the difference between SEO, AEO and GEO?</strong> SEO helps a website rank in Google&#039;s regular results. AEO structures content so search engines show it as a direct answer, such as a featured snippet. GEO helps a brand become a source that AI tools like ChatGPT and Google AI Overviews trust and cite in their answers.</p>\n<p><strong>Can I get a digital marketing job without a marketing degree?</strong> Yes. Agencies care more about proof of skill than the name of your degree. A portfolio with two or three documented projects, such as a local business audit or an AI visibility test, often matters more than marks. BBA, BCA, B.Com, BA and engineering students all work in the field.</p>\n<p><strong>Which digital marketing skill is most in demand for freshers?</strong> Search skills are among the most useful because every business needs to be found online. Understanding SEO and how AI tools choose sources gives freshers an edge. Clear writing and the ability to read analytics data come close behind, since they apply across every marketing role.</p>\n<p><strong>How long does it take to become job-ready in digital marketing?</strong> With about one hour a day, many students can become internship-ready in around 90 days. The first month covers foundations, the second builds two portfolio projects, and the third focuses on sharing work on LinkedIn and applying for internships.</p>\n<p><strong>Are free digital marketing certifications enough to get hired?</strong> Certificates alone rarely get you hired, but they show commitment. Free options from Google Skillshop, HubSpot Academy and Semrush Academy are widely recognised. Pair each certificate with a real project that shows you can apply what you learned.</p>\n<h2>About the Author</h2>\n<p>Abhishek Raikwar is the founder of <a href=\"https://digital4local.com/\" target=\"_blank\" rel=\"noopener\">Digital4Local</a>, a local SEO, AEO and AI search agency based in Bhopal working with UK and Indian businesses. He has 5+ years of SEO experience and holds an MBA in Marketing and Business Analytics. Connect with him on <a href=\"https://www.linkedin.com/in/abhishekraikwar-ai-expert/\" target=\"_blank\" rel=\"noopener\">LinkedIn</a>.</p>\n', 'upload/media/blog_digital_marketing_careers_2026_27.jpg', '0', '1', '2026-10-03 17:40:30', '2026-10-03 17:40:30');
